class PublicChildRetentionTests(unittest.TestCase):
    @unittest.skipUnless(os.name=='nt','actual PowerShell Process/collector failure requires Windows')
    def test_actual_cli_constructor_failure_retains_same_child_raw_and_unknown(self):
        import ast,base64,gzip,tempfile
        from pathlib import Path
        tree=ast.parse(Path(refresh.__file__).with_name('tests').joinpath('test_windows_cp117_base_source_refresh.py').read_text())
        capture=next(ast.literal_eval(n.value)for n in tree.body if isinstance(n,ast.Assign)and any(isinstance(t,ast.Name)and t.id=='STDIN_CAPTURE_CS'for t in n.targets))
        # An explicit one-shot constructor exception is the only failure seam.
        # Both actual collectors see the same real naturally exited cmd child.
        capture=capture.replace('public sealed class Cp117StdinCapture {','public sealed class Cp117StdinCapture { static int attempts=0;',1)
        capture=capture.replace('public Cp117StdinCapture(Stream stream,int cap){','public Cp117StdinCapture(Stream stream,int cap){if(Interlocked.Increment(ref attempts)==1){Thread.Sleep(700);throw new IOException("PUBLIC_SETUP_FAILURE");}',1)
        for packed,expected in ((PUBLIC_RETENTION_OLD_GZIP,False),(PUBLIC_RETENTION_CURRENT_GZIP,True)):
            template=gzip.decompress(base64.b64decode(packed,validate=True)).decode()
            definitions=template[template.index('function WriteBytes'):template.index('function Ok')]
            a=definitions.index('function PublicPrincipal');b=definitions.index('function Cli',a)
            definitions=definitions[:a]+'function PublicPrincipal{}\n'+definitions[b:]
            actual="$info=[Diagnostics.ProcessStartInfo]::new($cli,'--state-dir \"'+$state+'\" --json --timeout-seconds '+$seconds+$ownerArguments+' '+$command)"
            self.assertEqual(definitions.count(actual),1)
            definitions=definitions.replace(actual,"$info=[Diagnostics.ProcessStartInfo]::new($env:ComSpec,'/d /c echo PUBLIC_PREFIX')")
            with tempfile.TemporaryDirectory()as directory:
                root=directory.replace("'","''")
                script="$ErrorActionPreference='Stop';$root='"+root+"';$state='PUBLIC';$cli='PUBLIC';$deadline=[Diagnostics.Stopwatch]::StartNew();$phase='source-fixture';$sequence=0;$controller=$null;$revision=$null\nAdd-Type -TypeDefinition @'\n"+capture+"\n'@\n"+definitions+r'''
$failure=$null;try{$null=& ${function:Cli} 'status' 'status'}catch{$failure=$_.Exception.Message}
if($null -eq $failure){throw 'FAILURE_NOT_PRESERVED'}
[Console]::WriteLine('EXPECTED_FAILURE_RETAINED')
'''
                argument=factory()['complete_task_argument'](script)['argument']
