class PublicCarrierIngressTests(unittest.TestCase):
    def test_actual_complete_factory_and_real_public_frame_consumer_preserve_next_ack(self):
        import ast,base64,gzip,hashlib,sys
        original=gzip.decompress(base64.b64decode(PUBLIC_PARENT_SOURCE_GZIP,validate=True)).decode()
        body=gzip.decompress(base64.b64decode(PUBLIC_PHASE_CURRENT_GZIP,validate=True)).decode()
        frame=gzip.decompress(base64.b64decode(PUBLIC_PHASE_INPUT_GZIP,validate=True))
        validator="def validate(value):\n if type(value)is not dict or value.get('version')!=1 or type(value.get('version'))is not int:raise ValueError('public-fixture-schema')\n return value\n"
        source,sha,argument=factory()['public_phase_carrier'](original,body,'6815bdda-18db-42e7-8d48-99a7a8af39aa','90c25455-07b1-4663-b10a-d21aaee3a9c7',validator,frame)
        compile(source,'<string>','exec')
        old_ns={};exec(gzip.decompress(base64.b64decode(PUBLIC_CARRIER_LINE_RED_GZIP,validate=True)).decode(),old_ns)
        old_source,_,_=old_ns['public_phase_carrier'](original,body,'6815bdda-18db-42e7-8d48-99a7a8af39aa','90c25455-07b1-4663-b10a-d21aaee3a9c7',validator,frame)
        names=lambda text:{n.targets[0].id for n in ast.parse(text).body if isinstance(n,ast.Assign)and isinstance(n.targets[0],ast.Name)}
        self.assertFalse({'D','NONCE','BODY_SHA','ENCODED'}<=names(old_source))
        self.assertTrue({'D','NONCE','BODY_SHA','ENCODED'}<=names(source))
        self.assertLessEqual(len(source.encode()),131072)
        self.assertLess(len('"C:\\Windows\\System32\\WindowsPowerShell\\v1.0\\powershell.exe" '+argument),30000)
        self.assertEqual(sha,hashlib.sha256(body.encode('utf-16le')).hexdigest())
        tree=ast.parse(source)
        actual=next(n for n in ast.walk(tree)if isinstance(n,ast.FunctionDef)and n.name=='public_input_frame')
        reader=ast.get_source_segment(source,actual)
        # Execute the actual emitted input consumer in a real harmless Python
        # child. Only host/guest actions are omitted, not the consumer logic.
        script="import sys,hashlib,base64,json\ndef need(value,code):\n if not value:raise ValueError(code)\n"+reader+"\nv=public_input_frame();ack=sys.stdin.readline();print(json.dumps({'frame':v,'ack':ack}))\n"
        result=subprocess.run([sys.executable,'-c',script],input=frame+b'PUBLIC_NEXT_ACK\n',capture_output=True,timeout=5)
        self.assertEqual(result.returncode,0,result.stderr)
        observed=json.loads(result.stdout)
        self.assertEqual(base64.b64decode(observed['frame'],validate=True),frame)
        self.assertEqual(observed['ack'],'PUBLIC_NEXT_ACK\n')
        for malformed in (frame[:-1],b'x'+frame[1:]):
            refused=subprocess.run([sys.executable,'-c',script],input=malformed,capture_output=True,timeout=5)
            self.assertNotEqual(refused.returncode,0)
            self.assertEqual(refused.stdout,b'')
        constants={n.targets[0].id:ast.literal_eval(n.value)for n in tree.body if isinstance(n,ast.Assign)and len(n.targets)==1 and isinstance(n.targets[0],ast.Name)and n.targets[0].id in ('D','NONCE','BODY_SHA','ENCODED')}
        self.assertEqual(constants['BODY_SHA'],sha)
        self.assertEqual(constants['ENCODED'],argument.split('"',1)[1][:-1])
        self.assertEqual(source.count("'input-data':PUBLIC_INPUT"),1)
        self.assertIn("sys.stdin.readline().strip()==digest({'diagnosticId':D,'nonce':NONCE,'sourceSha256':BODY_SHA,'pid':pid})",source)
        self.assertNotIn("'-EncodedCommand',ENCODED",source)

