PUBLIC_OWNER_TOKEN_OLD_GZIP=''
PUBLIC_OWNER_TOKEN_CURRENT_GZIP=''


class PublicOwnerTokenProjectionTests(unittest.TestCase):
    def test_actual_old_current_scalar_guard_from_producer_order_and_elevation_projection(self):
        import base64,gzip,re
        old=gzip.decompress(base64.b64decode(PUBLIC_OWNER_TOKEN_OLD_GZIP,validate=True)).decode()
        current=gzip.decompress(base64.b64decode(PUBLIC_OWNER_TOKEN_CURRENT_GZIP,validate=True)).decode()
        old_guard=re.search(r"\$token\[1\] -ceq '2' -or \$token\[2\] -cne '0'",old).group()
        new_guard=re.search(r"\$token\[1\] -cne '0' -or \$token\[2\] -cne '3' -or \$token\[3\] -cne 'False'",current).group()
        def scalar_refuses(expression,token):
            parts=expression.split(' -or ');out=[]
            for item in parts:
                match=re.fullmatch(r"\$token\[([123])\] -(ceq|cne) '([A-Za-z0-9]+)'",item)
                if match is None:raise AssertionError('nonclosed scalar guard')
                i,op,expected=match.groups();out.append(token[int(i)]==expected if op=='ceq'else token[int(i)]!=expected)
            return any(out)
        # Token field order is the actual unchanged native producer contract:
        # SID, TokenElevation(20), TokenElevationType(18), member, enabled, session.
        token=['PUBLIC_SID','0','3','False','False','1']
        self.assertTrue(scalar_refuses(old_guard,token))
        self.assertFalse(scalar_refuses(new_guard,token))
        for i,v in ((1,'1'),(2,'2'),(3,'True')):
            foreign=token.copy();foreign[i]=v;self.assertTrue(scalar_refuses(new_guard,foreign))
        old_projection=re.search(r'elevationType=\[int\]\$token\[([12])\]',old).group(1)
        current_projection=re.search(r'elevationType=\[int\]\$token\[([12])\]',current).group(1)
        self.assertEqual(int(token[int(old_projection)]),0)
        self.assertEqual(int(token[int(current_projection)]),3)
        self.assertEqual(current.replace(new_guard,old_guard).replace('elevationType=[int]$token[2]','elevationType=[int]$token[1]'),old)

