class PublicContextFailureStageTests(unittest.TestCase):
    def exercise(self,runner,context_error=None,close_error=None):
        import tempfile,pathlib,gzip,base64
        from unittest.mock import patch
        source=gzip.decompress(base64.b64decode(PUBLIC_HOST_LOADER_GZIP))
        tracked=[];import os
        original_open=os.open
        def own_open(*args,**kwargs):
            fd=original_open(*args,**kwargs);tracked.append(fd);return fd
        class Inputs:
            def __init__(self,*args):pass
            def body(self,path):return source
            def close(self):pass
        def context(inputs):
            def bind(*args):
                if context_error:raise context_error
            def close():
                if close_error:raise close_error
            return {'interfaces':{'bind_host_interfaces':bind},'builders_namespace':{'make_builders':lambda c:{}},'verify':lambda:None,'close':close}
        def execute(code,ns):ns.update(PublicInputs=Inputs,assemble_context=context)
        with tempfile.TemporaryDirectory() as folder:
            root=pathlib.Path(folder).resolve();path=root/'public-host-main.draft.py';path.write_bytes(source);path.chmod(0o644)
            ns={'__name__':'actual_context_stage_entry','__file__':str(root/'runner.py')};exec(compile(runner,'<retained-entry>','exec'),ns);ns['exec']=execute
            class Observer:
                def __init__(self,folder):self.path=root/'private-observer';self.rows=[]
                def install(self):pass
                def close(self):pass
            ns['ControlRawObserver']=Observer
            try:
                with patch.object(os,'open',own_open):return ns['main']()
            finally:
                # Only this fixture's own descriptors, including old leaked
                # descriptors after its unguarded close, may be closed here.
                for fd in tracked:
                    try:os.close(fd)
                    except OSError:pass
    def test_actual_old_close_masks_first_context_failure(self):
        import gzip,base64
        runner=gzip.decompress(base64.b64decode(PREFLIGHT_PUBLIC_SOURCE_RUNNER_GREEN_GZIP)).decode()
        with self.assertRaisesRegex(RuntimeError,'SECONDARY_CLOSE'):
            self.exercise(runner,ValueError('outer-authority'),RuntimeError('SECONDARY_CLOSE'))
