PUBLIC_RECORDED_STAGE_BODY_SOURCE='def recorded_stage_body_sha(source):\n    tree=ast.parse(source)\n    values={}\n    for node in tree.body:\n        if isinstance(node,ast.Assign):\n            for target in node.targets:\n                if isinstance(target,ast.Name) and target.id in (\'ENCODED\',\'BODY_SHA\'):\n                    if target.id in values:raise ValueError(\'historical-stage-body-duplicate\')\n                    values[target.id]=ast.literal_eval(node.value)\n    if set(values)!= {\'ENCODED\',\'BODY_SHA\'} or any(type(x)is not str for x in values.values()) or len(values[\'BODY_SHA\'])!=64 or any(x not in \'0123456789abcdef\'for x in values[\'BODY_SHA\']):raise ValueError(\'historical-stage-body-schema\')\n    import re,zlib\n    encoded=values[\'ENCODED\']\n    if encoded.startswith("$ErrorActionPreference=\'Stop\';$i=[IO.MemoryStream]::new([Convert]::FromBase64String(\'"):\n        match=re.fullmatch(r"\\$ErrorActionPreference=\'Stop\';\\$i=\\[IO.MemoryStream\\]::new\\(\\[Convert\\]::FromBase64String\\(\'([A-Za-z0-9+/=]+)\'\\)\\);.*\\$v.Length -ne ([1-9][0-9]{0,4}) .* -cne \'([0-9a-f]{64})\'.*",encoded)\n        if match is None or int(match[2])>65536:raise ValueError(\'historical-stage-bootstrap-schema\')\n        decoder=zlib.decompressobj(16+zlib.MAX_WBITS);body=decoder.decompress(base64.b64decode(match[1],validate=True),int(match[2])+1)\n        if not decoder.eof or decoder.unused_data or decoder.unconsumed_tail or len(body)!=int(match[2])or hashlib.sha256(body).hexdigest()!=match[3]:raise ValueError(\'historical-stage-bootstrap-hash\')\n        full=body.decode(\'utf-8\',\'strict\');header,separator,plain=full.partition(\'\\n\')\n        marker=re.fullmatch(r"\\[Console\\]::Out.WriteLine\\(\\(\'CP117-READ ([0-9a-f-]{36}) ([0-9a-f]{64}) \'\\+\\$PID\\)\\)",header)\n        if not separator or marker is None or marker[2]!=values[\'BODY_SHA\']:raise ValueError(\'historical-stage-read-header\')\n        raw=plain.encode(\'utf-16le\')\n    else:\n        raw=base64.b64decode(encoded,validate=True);raw.decode(\'utf-16le\',\'strict\')\n    if not raw or len(raw)>131072 or hashlib.sha256(raw).hexdigest()!=values[\'BODY_SHA\']:raise ValueError(\'historical-stage-body-hash\')\n    return values[\'BODY_SHA\']\n'

class PublicRecordedStageBodyTests(unittest.TestCase):
    def test_actual_recorded_body_hash_replaces_historical_factory_rerender(self):
        import ast,base64,hashlib,tempfile,pathlib
        raw='Write-Output PUBLIC_RECORDED_BODY\n'.encode('utf-16le')
        source='ENCODED='+repr(base64.b64encode(raw).decode())+'\nBODY_SHA='+repr(hashlib.sha256(raw).hexdigest())+'\n'
        ns={'ast':ast,'base64':base64,'hashlib':hashlib};exec(PUBLIC_RECORDED_STAGE_BODY_SOURCE,ns)
        with tempfile.TemporaryDirectory()as td:
            path=pathlib.Path(td).resolve()/'recorded-remote.py';path.write_text(source)
            value=ns['recorded_stage_body_sha'](path.read_text())
            self.assertEqual(value,hashlib.sha256(raw).hexdigest())
            old={'download_body':lambda _:(_ for _ in ()).throw(ValueError('package-fixed-source'))}
            with self.assertRaisesRegex(ValueError,'^package-fixed-source$'):hashlib.sha256(old['download_body'](54935)[0].encode('utf-16le')).hexdigest()
            for changed in (source+"BODY_SHA='"+'0'*64+"'\n",source.replace(value,'0'*64),source.replace('ENCODED=','FOREIGN='),source.replace(base64.b64encode(raw).decode(),'!')):
                with self.assertRaises(Exception):ns['recorded_stage_body_sha'](changed)

PUBLIC_CURRENT_TEST_SUCCESSOR_SOURCE="def verify_current_test_successor(old_raw,current_raw,old_sha,current_sha,allowed_methods):\n    if hashlib.sha256(old_raw).hexdigest()!=old_sha or hashlib.sha256(current_raw).hexdigest()!=current_sha:raise ValueError('current-test-successor-hash')\n    old=ast.parse(old_raw);current=ast.parse(current_raw)\n    imports=[n for n in current.body if isinstance(n,ast.ImportFrom)and n.module=='agent_tools.tests.fixtures.windows_cp117_historical_factory.context']\n    if len(imports)!=1 or [(n.name,n.asname)for n in imports[0].names]!=[('HistoricalFactoryTestCase','HistoryCase'),('provider','historical_provider')]:raise ValueError('current-test-successor-import')\n    current.body.remove(imports[0]);changed=set()\n    for node in current.body:\n        if not isinstance(node,ast.ClassDef):continue\n        for index,base in enumerate(node.bases):\n            if isinstance(base,ast.Name)and base.id=='HistoryCase':node.bases[index]=ast.Attribute(value=ast.Name(id='unittest',ctx=ast.Load()),attr='TestCase',ctx=ast.Load())\n        old_class=next((n for n in old.body if isinstance(n,ast.ClassDef)and n.name==node.name),None)\n        if old_class is None:raise ValueError('current-test-successor-class')\n        for index,method in enumerate(node.body):\n            if not isinstance(method,ast.FunctionDef):continue\n            name=node.name+'.'+method.name\n            if name in allowed_methods:\n                prior=next(n for n in old_class.body if isinstance(n,ast.FunctionDef)and n.name==method.name)\n                if ast.dump(method,include_attributes=False)==ast.dump(prior,include_attributes=False):raise ValueError('current-test-successor-declared-delta')\n                node.body[index]=prior;changed.add(name)\n    if changed!=set(allowed_methods)or ast.dump(current,include_attributes=False)!=ast.dump(old,include_attributes=False):raise ValueError('current-test-successor-undeclared-delta')\n"

class PublicCurrentTestSuccessorTests(unittest.TestCase):
    def test_exact_archive_and_declared_test_changes_only(self):
        import ast,hashlib
        old=b'import unittest\nclass Case(unittest.TestCase):\n def test_body(self): return 1\nFACTORY="fixed"\n'
        new=b'from agent_tools.tests.fixtures.windows_cp117_historical_factory.context import HistoricalFactoryTestCase as HistoryCase, provider as historical_provider\nimport unittest\nclass Case(HistoryCase):\n def test_body(self): return 2\nFACTORY="fixed"\n'
        ns={'ast':ast,'hashlib':hashlib};exec(PUBLIC_CURRENT_TEST_SUCCESSOR_SOURCE,ns);sha=lambda raw:hashlib.sha256(raw).hexdigest()
        ns['verify_current_test_successor'](old,new,sha(old),sha(new),('Case.test_body',))
        for oldraw,current in ((old+b'#foreign',new),(old,new.replace(b'fixed',b'foreign'))):
            with self.assertRaises(ValueError):ns['verify_current_test_successor'](oldraw,current,sha(old),sha(current),('Case.test_body',))
        with self.assertRaises(ValueError):ns['verify_current_test_successor'](old,new,sha(old),sha(new),())

